#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    // Initialize output bins
    bins.fill(0);

    const int maxThreads = omp_get_max_threads();
    std::vector<std::array<size_t, 10>> local(static_cast<size_t>(maxThreads));
    for (int t = 0; t < maxThreads; ++t) local[static_cast<size_t>(t)].fill(0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &lb = local[static_cast<size_t>(tid)];

        #pragma omp for schedule(static_cast<omp_sched_t>(omp_sched_static))
        for (std::size_t i = 0; i < x.size(); ++i) {
            double v = x[i];

            // Values are specified to be in [0, 100], inclusive.
            // Bin index: [0,10)->0, [10,20)->1, ..., [90,100]->9
            int b = static_cast<int>(v / 10.0);
            if (b < 0) b = 0;
            if (b > 9) b = 9;

            lb[static_cast<std::size_t>(b)]++;
        }
    }

    // Combine thread-local bins (serial, no races)
    for (int t = 0; t < maxThreads; ++t) {
        for (int b = 0; b < 10; ++b) {
            bins[static_cast<std::size_t>(b)] += local[static_cast<std::size_t>(t)][static_cast<std::size_t>(b)];
        }
    }
}
